"""Persist five complete bodies, qualified mathematical claims and exact controls."""
import hashlib
import json
from pathlib import Path

R = Path(__file__).resolve().parents[2]
P = R/'dag/reviews/additional_rust_linear_algebra_remaining'
path = Path(str(P)+'_notes.json')
notes = json.loads(path.read_bytes())
pins = {x['path']: x['sha256'] for x in json.loads(Path(str(P)+'_scope.json').read_bytes())['files']}
assessments = {
    'src/exact_field/laws.rs': 'Read all583 lines in two complete ranges. Finite unary/pair/triple checks cover field identities, inverses, commutativity, associativity and distributivity, with separate conjugation and order predicates. The documentation correctly says finite passes are sample evidence, not universal proof; empty samples still check only a few constants. These checkers do not mutually invoke one another, so callers must supply the complete intended suite. Derived norm values receive a weaker sign test: a Gaussian sample0,1,-1,4+i with a defective sign2 only at real17 passes because norm checking accepts any nonnegative sign, while adding17 itself triggers domain refusal. Substantive tests include small complete finite fields and deliberately defective scalars, plus an exact negative Galois norm; their Galois-versus-complex-conjugation wording should remain distinguished. All assertions were read, not executed. Unrelated capacity boilerplate supplies no law-checker mutation evidence.',
    'src/exact_field/test_support.rs': 'Read all702 lines in three complete ranges. Test-only owner defines canonical rational constructors, deterministic SplitMix64 inputs, small prime-field arithmetic, Z/6 nonunit refusals, exact Gaussian-rational and Q(sqrt2) arithmetic and intentionally defective Shaky variants. The quadratic sign comparison is exact under rational canonicality and irrationality of sqrt2; its involution is identity, distinct from Galois conjugation. Small shipped finite-field parameters fit fixed-width operations; arbitrary const P is not safely admitted by primality alone because P-as-i64 conversion and u64 multiplication need additional range bounds. Generator dimensions/ranges likewise assume small trusted fixture inputs. These limitations concern test helpers, not an observed production failure; deliberate Shaky modes are negative controls, not accidental defects. Test scalar routes sharing these operations are not fully independent arithmetic implementations. No source execution; repeated capacity tests remain unrelated to surrounding algebra.',
    'src/exact_field/neville_aitken.rs': 'Read all324 lines. Nonempty distinct canonical nodes, matching sample counts and valid ordered intervals are checked before the Neville recurrence. The shared RationalBudget is passed through scalar steps, endpoint arithmetic, comparisons and allocations. Recursive interval propagation is a conservative enclosure because repeated dependencies can widen bounds; the independently formed Lagrange weights give the exact linear image of the sample box. Neither implies a function approximation remainder, asymptotic limit or empirical prediction, as the source states. A finite independent900-case control checks2412 prefixes against corner extrema and gives an explicit strict-enclosure example. The sole embedded test checks literal Ok/Err and does not exercise interpolation or justify the six-mutant comment. No original execution.',
    'src/exact_field/rational_bareiss.rs': 'Read all706 lines in two complete ranges. Mutable caller-owned fuel is shared through canonical-rational admission, arithmetic, row-denominator clearing, fraction-free exact divisions, back substitution and final original-equation replay. Raw zero/negative denominators and unreduced pairs are rejected, improving the generic exact-field ingress. Free columns are set to zero; Inconsistent is a typed producer refusal, explicitly not a dual inconsistency certificate, and replay failure uses that same category. Destination mutation on exhausted in-place matvec is explicitly documented as partial. Exposed integer/rational values are checked against max_bits after arithmetic, but dependency arithmetic can create larger temporaries before reduction:3/2+3/2 passes a2-bit value bound while constructing numerator6. Per-collection element bounds and scalar-call fuel are not elapsed time or total allocation guarantees. Independent921 systems agree with rational Gauss-Jordan and replay627 solutions, with7558 exact integer divisions. Embedded tests meaningfully cover rectangular/singular/empty cases, canonicality, bit/fuel refusal and cross-solver comparison; not run.',
    'src/exact_field/second_order_jet.rs': 'Read all198 lines. Private equal-square-shape triples store value, first derivative and second derivative rather than Taylor coefficients. Product preserves matrix order and uses A2*B0+2*A1*B1+A0*B2, with an aggregate preflight for six products, three additions, one scale and constructing2. This is a substantive truncated formal product rule; actual analytic curves or arbitrary jet realizability over small characteristic are not established by shape admission. Independent64 rational2x2 polynomial-curve pairs agree with coefficient convolution and derivative conversion. Embedded tests cover only unrelated count/capacity metadata, so no native jet tests or original execution are claimed.'
}
for name, text in assessments.items():
    notes['files'][name] = {'full_source_read': True, 'assessment': text}
notes['files']['src/exact_field/involution.rs']['assessment'] = notes['files']['src/exact_field/involution.rs']['assessment'].replace('test-support arithmetic remains a separately pending owner', 'test-support arithmetic is now fully read with its small-fixture limitations recorded')

def ev(name, lo, hi):
    p = 'code/rust/core_linear_algebra/'+name
    return {'path': p, 'sha256': pins[p], 'lines': [lo, hi]}

claims = [
    {'id': 'RLA-C17', 'statement': 'The scalar-law owners implement explicit finite field, involution and order checks and correctly distinguish sampled passes from universal trait proofs. Their arithmetic test carriers include exact rational quadratic extensions and deliberate negative controls; consumers still need the relevant complete set of premises.', 'evidence': [ev('src/exact_field/laws.rs', 1, 29), ev('src/exact_field/laws.rs', 42, 133), ev('src/exact_field/laws.rs', 136, 260), ev('src/exact_field/test_support.rs', 239, 299), ev('src/exact_field/test_support.rs', 341, 425)], 'controls': ['RLA-P22'], 'limits': 'No retained tests executed; incomplete samples, missing combined checks, fixed-width fixture bounds and the derived-norm sign gap prevent blanket certification of arbitrary scalar implementations.'},
    {'id': 'RLA-C18', 'statement': 'A shared caller-owned rational budget composes canonical-value checks and fraction-free solving through final equation replay. On distinct rational nodes, Neville evaluation computes finite interpolants; Lagrange interval images are tight for the admitted independent sample box, while recursive interval propagation can be wider.', 'evidence': [ev('src/exact_field/rational_bareiss.rs', 47, 158), ev('src/exact_field/rational_bareiss.rs', 416, 439), ev('src/exact_field/neville_aitken.rs', 1, 13), ev('src/exact_field/neville_aitken.rs', 167, 306)], 'controls': ['RLA-P23', 'RLA-P24'], 'limits': 'Independent921 systems and900 interval cases only. Scalar-call fuel and exposed-value bit limits are not elapsed-time or total-heap bounds. No inconsistency certificate, function remainder, convergence theorem or original execution.'},
    {'id': 'RLA-C19', 'statement': 'The matrix jet owner implements the ordered second-derivative product rule with the factor2 on the cross term and a whole-product arithmetic preflight. Rational polynomial-curve controls agree with independent coefficient convolution.', 'evidence': [ev('src/exact_field/second_order_jet.rs', 1, 22), ev('src/exact_field/second_order_jet.rs', 33, 79)], 'controls': ['RLA-P25'], 'limits': '64 independent rational2x2 jet pairs, no native execution or analytic existence theorem. Shape admission alone does not establish that arbitrary derivative triples arise from curves over every coefficient field.'}
]
findings = [
    {'id': 'RLA-F09', 'statement': 'The Hermitian-order sample checker validates sign range on supplied samples but accepts any nonnegative sign on a computed norm. A valid Gaussian arithmetic/involution with fixed_field_sign(17)=Some(2) passes samples0,1,-1,4+i even though the checker itself queries the invalid sign on norm(4+i)=17.', 'evidence': [ev('src/exact_field/laws.rs', 202, 260)], 'controls': ['RLA-P22'], 'limits': 'Independent exact model of the full checker path. This concerns its treatment of a value it actually evaluates, not a demand that finite samples prove universal laws. Adding17 to the sample exposes the defect.', 'recommended_action': 'Apply the same fixed-sign domain/range validation to every generated norm before checking positivity and zero equivalence.'},
    {'id': 'RLA-F10', 'statement': 'The rational-budget description overstates its bit bound as covering every intermediate integer. Its checks admit operands and returned normalized values, while num-rational arithmetic constructs temporary numerators first:3/2+3/2 creates6 before reducing to3, and the operation succeeds with max_bits=2.', 'evidence': [ev('src/exact_field/rational_bareiss.rs', 1, 9), ev('src/exact_field/rational_bareiss.rs', 82, 123), ev('src/exact_field/rational_bareiss.rs', 134, 156)], 'controls': ['RLA-P26'], 'limits': 'Pinned num-rational0.4.2 addition excerpts and exact arithmetic, not native allocation measurement. Accepted exposed values are bounded; the source already disclaims CPU/bit-operation accounting.', 'recommended_action': 'Document the bound as applying to admitted and returned values, or use a scalar implementation that checks temporary-size growth before arithmetic if that stronger resource contract is needed.'}
]
for group, items in [('claims', claims), ('findings', findings)]:
    ids = {x['id'] for x in items}
    notes[group] = [x for x in notes[group] if x['id'] not in ids]+items
receipt = Path(str(P)+'_controls08.json')
result = json.loads(receipt.read_bytes())
assert result['status'] == 'finite_controls_pass'
assert hashlib.sha256(receipt.with_suffix('.py').read_bytes()).hexdigest() == result['helper_sha256']
ids = {x['id'] for x in result['controls']}
notes['controls'] = [x for x in notes['controls'] if x['id'] not in ids]
for item in result['controls']:
    notes['controls'].append({**item, 'receipt': {'path': receipt.relative_to(R).as_posix(), 'sha256': hashlib.sha256(receipt.read_bytes()).hexdigest()}})
path.write_text(json.dumps(notes, indent=2, ensure_ascii=False)+'\n', encoding='utf8')
print('Persisted five complete bodies, three claims, two qualified findings and five controls.')
